import 'package:flutter/material.dart';
import '../models/masonry_result.dart';
class MasonryDiagram extends StatelessWidget { final MasonryType type; const MasonryDiagram({super.key,required this.type}); @override Widget build(BuildContext context)=>SizedBox(height:140,width:double.infinity,child:CustomPaint(painter:_MasonryPainter(type))); }
class _MasonryPainter extends CustomPainter { final MasonryType type; _MasonryPainter(this.type); @override void paint(Canvas c,Size s){ final line=Paint()..color=const Color(0xff145da0)..style=PaintingStyle.stroke..strokeWidth=2; final fill=Paint()..color=const Color(0x33145da0); final r=Rect.fromLTWH(s.width*.16,s.height*.2,s.width*.68,s.height*.58); c.drawRect(r,fill); c.drawRect(r,line); final step=type==MasonryType.clayBrick?16:28; for(double y=r.top+step;y<r.bottom;y+=step){c.drawLine(Offset(r.left,y),Offset(r.right,y),line);} for(double x=r.left+step;x<r.right;x+=step){c.drawLine(Offset(x,r.top),Offset(x,r.bottom),line);} final text=TextPainter(text:TextSpan(text:'L',style:const TextStyle(color:Color(0xff145da0),fontWeight:FontWeight.bold)),textDirection:TextDirection.ltr)..layout();text.paint(c,Offset(r.center.dx,r.bottom+6)); final h=TextPainter(text:TextSpan(text:'H',style:const TextStyle(color:Color(0xff145da0),fontWeight:FontWeight.bold)),textDirection:TextDirection.ltr)..layout();h.paint(c,Offset(r.right+8,r.center.dy)); } @override bool shouldRepaint(covariant _MasonryPainter old)=>old.type!=type; }
